def generate_redirect_link(base_url, endpoint_path, query_info=None):

    if not isinstance(base_url, str):
        raise ValueError("Invalid base_url type")
    if not isinstance(endpoint_path, str):
        raise ValueError("Invalid endpoint_path type")
    if query_info is not None and not isinstance(query_info, dict):
        raise ValueError("Invalid query_info type")

    parsed_url = urllib.parse.urlparse(base_url)
    if parsed_url.netloc not in APPROVED_API_DOMAINS:
        raise ValueError("Unapproved API domain")

    if endpoint_path not in ALLOWED_ENDPOINTS:
        raise ValueError("Unapproved endpoint")

    full_url = urllib.parse.urlunparse((
        parsed_url.scheme,
        parsed_url.netloc,
        endpoint_path,
        parsed_url.params,
        urllib.parse.urlencode(query_info),
        parsed_url.fragment
    ))

    return full_url

