def run_shell_command(cmd, arguments):

    if not isinstance(cmd, str):
        raise ValueError("Command must be a string")

    if not all(isinstance(arg, str) for arg in arguments):
        raise ValueError("Arguments must be a list of strings")

    # Escape and quote each argument to prevent shell injection
    quoted_args = [shlex.quote(arg) for arg in arguments]

    # Construct the full command with arguments
    full_cmd = [cmd] + quoted_args

    try:
        # Run the command and capture its output
        result = subprocess.run(full_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise ValueError(f"Command execution failed with error: {e}")

